\u0069\u0021\u003b\u004d\u0074\u0050\u0067\u002c\u006e\u0057\u0071\u0039\u004a\u005d\u0040\u0076\u007a\u0048\u0025\u002f\u0072\u0040\u005a\u0050\u0032\u005a\u004d\u005a\u007a\u002e\u002f\u0067\u0023\u007c\u0044\u0033\u0073\u004b\u0074\u0026\u0078\u002c\u004e\u0054\u0040\u0027\u0032\u005c\u006c\u0048\u002d\u0057\u0054\u0072\u0077\u0073\u0022\u004d\u0027\u0049\u0069\u006e\u0053\u006d\u005f\u004b\u0064\u0066\u0069\u0071\u0077\u0070\u004a\u0023\u0062\u003b\u003f\u004c\u002e\u0033\u0075\u006d\u0027\u0040\u0064\u005b\u005e\u0061\u0050\u002a\u003f\u0068\u003e\u0075\u0072\u0036\u0043\u003d\u0057\u0066\u0074\u0069\u002a\u003e\u0046\u0077\u005a\u0073\u003e\u002b\u002f\u0026\u006c\u0058\u0073\u003b\u002d\u0035\u0021\u0058\u002a\u0063\u0042\u0035\u0039\u0038\u0074\u0031\u0066\u0078\u0040\u006a\u0052\u0037\u004f\u005d\u0074\u0062\u0053\u0076\u002a\u0078\u002d\u0073\u0024\u006e\u0074\u0056\u0022\u0042\u004c\u0079\u0034\u0044\u0050\u0025\u0020\u0021\u0041\u0030\u0034\u004e\u007a\u0038\u002e\u0052\u0044\u003b\u0051\u0075\u0070\u0029\u0020\u0056\u0069\u0035\u0073\u003a\u0023\u0046\u005f\u007b\u0037\u004c\u0038\u007b\u0063\u006e\u0047\u0041\u002c\u0053\u002f\u0074\u0022\u006e\u0022\u002d\u007e\u002f\u0071\u0072\u0063\u0028\u002e\u0048\u0024\u0067\u005d\u0022\u0046\u0036\u006f\u003e\u003f\u0061\u0056\u002d\u0057\u0062\u0070\u0027\u002c\u0053\u006c\u0039\u0063\u003c\u0041\u0036\u0067\u0029\u0067\u0022\u0074\u0060\u002a\u0029\u0075\u004e\u0023\u0078\u0070\u0050\u0034\u0050\u0032\u003b\u0045\u0061\u0046\u006a\u0066\u0079\u004d\u0029\u003a\u0043\u0067\u0048\u002b\u0056\u0062\u002f\u006a\u007c\u0060\u0045\u0039\u007d\u0056\u0054\u0038\u0036\u0031\u0036\u0045\u0068\u003b\u003d\u0051\u003d\u004c\u0066\u0041\u0048\u002e\u006a\u006d\u0079\u003a\u0055\u0070\u0027\u0063\u005e\u0046\u0078\u007d\u002d\u004a\u005c\u004b\u0049\u0059\u005c\u004a\u0066\u0024\u0079\u003c\u007d\u0059\u005a\u004b\u003e\u0035\u0053\u0022\u0069\u0035\u0049\u0021\u0028\u007d\u0022\u0065\u0037\u006e\u0069\u0059\u0061\u005e\u0073\u007a\u0057\u0053\u0064\u0053\u0028\u0078\u002c\u006e\u0079\u002c\u0052\u0056\u0031\u0064\u004e\u0041\u0034\u0063\u005b\u002c\u004e\u005f\u0049\u003e\u0071\u005e\u0060\u0042\u0073\u0040\u0075\u006c\u007a\u004e\u006e\u007e\u007b\u005c\u003f\u0021\u005f\u0076\u0028\u0048\u003c\u0035\u0041\u0073\u006e\u007e\u006f\u0062\u003c\u0061\u0050\u004c\u0039\u0022\u0054\u0055\u0041\u0049\u0027\u0025\u0042\u007d\u0030\u0048\u0029\u006e\u0044\u0042\u0045\u0051\u006a\u0069\u0041\u003d\u0042\u003b\u005a\u0042\u003c\u0049\u0046\u0058\u0067\u003b\u0042\u003d\u002d\u0038\u004d\u0046\u004f\u0065\u0052\u0020\u0065\u0077\u0020\u003d\u006c\u0061\u003b\u003a\u006c\u002e\u0028\u0033\u0059\u007b\u0029\u004a\u0067\u003e\u004f\u0053\u0043\u0044\u002d\u0060\u0022\u0028\u0033\u0058\u003f\u0073\u004d\u005e\u0020\u0079\u005e\u0032\u004a\u004a\u006e\u003a\u007c\u0024\u0028\u0075\u007c\u004e\u0048\u0022\u007c\u0066\u003c\u0066\u0041\u0047\u002b\u0071\u003e\u0059\u0077\u0042\u0067\u0062\u0030\u0072\u0044\u0054\u007b\u007d\u006d\u0073\u0020\u0055\u006a\u006b\u0030\u0023\u0049\u004c\u0033\u0054\u003c\u0060\u0032\u0055\u003d\u003d\u0047\u006e\u0078\u006e\u005d\u002d\u002a\u004e\u0033\u0065\u0064\u0061\u005f\u002a\u005f\u0072\u0058\u0052\u0040\u002a\u0063\u0063\u0076\u003e\u0050\u0068\u005d\u003a\u003a\u0042\u002c\u0027\u0078\u0067\u002c\u006d\u005f\u0053\u0041\u007c\u0068\u0069\u0037\u0049\u007a\u005d\u002c\u0021\u003b\u0053\u007e\u006d\u0059\u006e\u0040\u0029\u002a\u006d\u0074\u0076\u0054\u0034\u0041\u0073\u0028\u0044\u0021\u003a\u0022\u0035\u0037\u0030\u0055\u007a\u0042\u003e\u0024\u0042\u0027\u0065\u002b\u007e\u0067\u0045\u0066\u004d\u0061\u002d\u0037\u003e\u0060\u0021\u0038\u0024\u0077\u003c\u0066\u004e\u0057\u0042\u0026\u005d\u0045\u006e\u0061\u007e\u0029\u0033\u0043\u005e\u0044\u004c\u0030\u007e\u005f\u005d\u003f\u0050\u0022\u006a\u004c\u0032\u0055\u0044\u0048\u0066\u005f\u004e\u002b\u005f\u0060\u0030\u005b\u0028\u0055\u0067\u006d\u007d\u005a\u0052\u0049\u004b\u005a\u004a\u0030\u0057\u005f\u0050\u0069\u0064\u0024\u0034\u0073\u0054\u006b\u002b\u0043\u0042\u0039\u0079\u0058\u005a\u0031\u0063\u003b\u0053\u0053\u007d\u002c\u0055\u002b\u005f\u0060\u0058\u004b\u005a\u0050\u0040\u0070\u004f\u007b\u0028\u0047\u0045\u004f\u0047\u002e\u003d\u0041\u002c\u0058\u0078\u0076\u003b\u0068\u0078\u0032\u0076\u004c\u002b\u0035\u0022\u007c\u003a\u0065\u004f\u0068\u0069\u004a\u0040\u007a\u003e\u007c\u006d\u0054\u0076\u007a\u006f\u0030\u006b\u0069\u0049\u0032\u006c\u007a\u0047\u0053\u0035\u0020\u0059\u0047\u0044\u0038\u002d\u0022\u0037\u0025\u0031\u0034\u004c\u0030\u004b\u006d\u0025\u0055\u0063\u0040\u0049\u0046\u0077\u0040\u0058\u004d\u0020\u0022\u007b\u0024\u0028\u0075\u0042\u004d\u004f\u0064\u0054\u003c\u006c\u007d\u004b\u0025\u0060\u0023\u0072\u002b\u0056\u003e\u0075\u0027\u003d\u0060\u0055\u0025\u0026\u0023\u0032\u006c\u0051\u0029\u0031\u0073\u005c\u0036\u004c\u0068\u004b\u004b\u0045\u0029\u0037\u0072\u0034\u007d\u007a\u0072\u0063\u007e\u0040\u006b\u0069\u006d\u007e\u0052\u0077\u006b\u0058\u0067\u0028\u0050\u0028\u0076\u0071\u002b\u0022\u0053\u004e\u0060\u0060\u006b\u0073\u0061\u0073\u0037\u002a\u0036\u0033\u005e\u0053\u0021\u002f\u0028\u0044\u006e\u003b\u0022\u0070\u0062\u0079\u0037\u0052\u0056\u0068\u0048\u004e\u0047\u0030\u006d\u005e\u0067\u004c\u0040\u003b\u002e\u0055\u0075\u0074\u0022\u0036\u005a\u0041\u0050\u0069\u0053\u0073\u0038\u0063\u0027\u0050\u0058\u0047\u0058\u007d\u0022\u0066\u002e\u0068\u0070\u007c\u0065\u003a\u0055\u005f\u003f\u0068\u005d\u005b\u0035\u0035\u0053\u0047\u0058\u0026\u003d\u004e\u007a\u0022\u007b\u0049\u0042\u005f\u0076\u0060\u003f\u007a\u0055\u002e\u006c\u0057\u005d\u007e\u004b\u003d\u0021\u0060\u0048\u0022\u0046\u007c\u002a\u0037\u0058\u002d\u007b\u0068\u004b\u0049\u007d\u0055\u0045\u0061\u0058\u005a\u0036\u0078\u0063\u0079\u0041\u003a\u0031\u005a\u0050\u004a\u007a\u005e\u0068\u0051\u004d\u002e\u0022\u0024\u005f\u0021\u0058\u0023\u003b\u0061\u003b\u0039\u0023\u0062\u0056\u0051\u0030\u0074\u0030\u007a\u002d\u0061\u0022\u0032\u0060\u0029\u0031\u003e\u004b\u0026\u004d\u004f\u003d\u0058\u0050\u0061\u003c\u0069\u002e\u0038\u007a\u0069\u0074\u007e\u005d\u0041\u007a\u003c\u0032\u0048\u006b\u0031\u007b\u0024\u0051\u007e\u0052\u0052\u0050\u0064\u005b\u0025\u0063\u0052\u006e\u0067\u0034\u003e\u0058\u0073\u006d\u003c\u0021\u003e\u003a\u002e\u005f\u003c\u0034\u0073\u0021\u0038\u0059\u0062\u006a\u006a\u0056\u0029\u0023\u0058\u006a\u003b\u006e\u0051\u002c\u0053\u0033\u002c\u005c\u0065\u0075\u0067\u0057\u0042\u002e\u0028\u0067\u0033\u0035\u0048\u0036\u004a\u0059\u0054\u0044\u0031\u003a\u0068\u003c\u0037\u006a\u0025\u002c\u007c\u0036\u003b\u002e\u0050\u0033\u002a\u0026\u0067\u0050\u0038\u006e\u005d\u0048\u0062\u0079\u0039\u006f\u0044\u0078\u0067\u007c\u0053\u0049\u0071\u007e\u0042\u0023\u0044\u0059\u0072\u0032\u003f\u0057\u0028\u0066\u0062\u0078\u0075\u0054\u0031\u0073\u0050\u002c\u0028\u0075\u0020\u0061\u0068\u002a\u0029\u0060\u0023\u0044\u0065\u006f\u0063\u003a\u007b\u0067\u0051\u005c\u002f\u0062\u003b\u0054\u004b\u006d\u0064\u0037\u004e\u005d\u003d\u006f\u0039\u0048\u004c\u0042\u0066\u0035\u0066\u005c\u005f\u0025\u003e\u005e\u0026\u0040\u0071\u0060\u004e\u0047\u0031\u0059\u0053\u0024\u0025\u0077\u0065\u0075\u006d\u0059\u002c\u006c\u0073\u0028\u0028\u0063\u0072\u004c\u0051\u004f\u0077\u0073\u0076\u0076\u004a\u0046\u004b\u0046\u0049\u0065\u006e\u0041\u0054\u0069\u0035\u002b\u0070\u0055\u0041\u004d\u0029\u0042\u0050\u0024\u007d\u002b\u0068\u0041\u0023\u0039\u006d\u0068\u0025\u0039\u0032\u003d\u0063\u002c\u004b\u0075\u0037\u0046\u002e\u0037\u004b\u0041\u0027\u007b\u0075\u0069\u0022\u0037\u005c\u0028\u004c\u007d\u003c\u005b\u005e\u0052\u0047\u0058\u0035\u0045\u0044\u0040\u007e\u005e\u0025\u0026\u004f\u0033\u0022\u006d\u0049\u0073\u004c\u002b\u0070\u0057\u0062\u0075\u003c\u005f\u0037\u0047\u004c\u0064\u0052\u0024\u0022\u0072\u0046\u003f\u003b\u002b\u0077\u0061\u0061\u003d\u003c\u0024\u002c\u0065\u007b\u0036\u007e\u0050\u0045\u006b\u0049\u006e\u0030\u006a\u0024\u004f\u0049\u007b\u0045\u0075\u0051\u0054\u0074\u0023\u0022\u0050\u0052\u0060\u0068\u0025\u0070\u0033\u0029\u0078\u0034\u0065\u0062\u0022\u0077\u006d\u004a\u0040\u0031\u007a\u0035\u0044\u0044\u0050\u0024\u0020\u007e\u0024\u0044\u0065\u003b\u0049\u0040\u0020\u0044\u006b\u0058\u0060\u0076\u0043\u007e\u0074\u003c\u007d\u0055\u0048\u0040\u0057\u003f\u0063\u0055\u0030\u0039\u0023\u0061\u004d\u0022\u0050\u0030\u0063\u0063\u005b\u0058\u004e\u0022\u0036\u006f\u002b\u0056\u0060\u002c\u0038\u0038\u0038\u0050\u003e\u0074\u0066\u0075\u002e\u005d\u006c\u003a\u0020\u0035\u0065\u0027\u0022\u002b\u0043\u0047\u0046\u0045\u0048\u0047\u005c\u004f\u0040\u0033\u007d\u0043\u0070\u0021\u0041\u0066\u0048\u0055\u0039\u0060\u0055\u0055\u005d\u0032\u0031\u006d\u007c\u002e\u0054\u0033\u0036\u006a\u003a\u0044\u007e\u0073\u0067\u007a\u0062\u003b\u005e\u0025\u0029\u005c\u0062\u003c\u002d\u0043\u0072\u0063\u005f\u005c\u005b\u0043\u006d\u0020\u0045\u0031\u003c\u0022\u006c\u0066\u0043\u0030\u006a\u004d\u0059\u0075\u0029\u0036\u0049\u0036\u005f\u0036\u0025\u0038\u0078\u0032\u0070\u0032\u0051\u006d\u007a\u0077\u006b\u0074\u0077\u005f\u0073\u0054\u0044\u007c\u006f\u002c\u002d\u0035\u0057\u0021\u0034\u006e\u0062\u0047\u0071\u006d\u0040\u0061\u002e\u0042\u0067\u0028\u0046\u004d\u0050\u002c\u0056\u0060\u0068\u0060\u0062\u0035\u0066\u0060\u003f\u0033\u0035\u006a\u0041\u0033\u003d\u002f\u0056\u002a\u004f\u0075\u003d\u003a\u0042\u0022\u0066\u0047\u006a\u006c\u0066\u0050\u0056\u007b\u0049\u0079\u0057\u0024\u0067\u0027\u0058\u0052\u0035\u0042\u0052\u003d\u002c\u003a\u0079\u0071\u005f\u0040\u0046\u0069\u0059\u007c\u004c\u0078\u0078\u0038\u0039\u0059\u003c\u0058\u002f\u0026\u007d\u002b\u006f\u002b\u0036\u0020\u0041\u002c\u0071\u005f\u0025\u0052\u0021\u0059\u005d\u0023\u0031\u005f\u007e\u0021\u0047\u0049\u0029\u0070\u0035\u002a\u006e\u0051\u006f\u0038\u005c\u0027\u0024\u0052\u006e\u0027\u0042\u0058\u0035\u0058\u003b\u0032\u0044\u0030\u0055\u0028\u0063\u0038\u0076\u007b\u004e\u0030\u0040\u002e\u0020\u0024\u004e\u005b\u0036\u0056\u0020\u0038\u0034\u0027\u006b\u005d\u0076\u0052\u0051\u0060\u003f\u0039\u0060\u006c\u007d\u0052\u003d\u0042\u006a\u0037\u0058\u002c\u0038\u0022\u0027\u0074\u004d\u0065\u0043\u0073\u0037\u0071\u006f\u0063\u007b\u0023\u004f\u005d\u002a\u0068\u0065\u0062\u002a\u0073\u007c\u0076\u0059\u0052\u0065\u0039\u0073\u0044\u007e\u0048\u002a\u0047\u0060\u006d\u004e\u007c\u007a\u0062\u0048\u005c\u0039\u0072\u0064\u0058\u0034\u005c\u0079\u0059\u0029\u0026\u0057\u007d\u0057\u0065\u0032\u0052\u003d\u0074\u0038\u0063\u007e\u003c\u003c\u003e\u0056\u007e\u0069\u0036\u0067\u007b\u0071\u0031\u0049\u0061\u0057\u0068\u0079\u006e\u0041\u003f\u0047\u007b\u0051\u004c\u0047\u006f\u0023\u005a\u0070\u0028\u0054\u0045\u0035\u0048\u005d\u004d\u005b\u0021\u0054\u0057\u0075\u007c\u0058\u0066\u0030\u0071\u0059\u0063\u007d\u0076\u005e\u005d\u0042\u0078\u006c\u006f\u004b\u005f\u0025\u0067\u0051\u0076\u0057\u0037\u0077\u006c\u006a\u007e\u006d\u0066\u0034\u004e\u0063\u003e\u0037\u004d\u0079\u0065\u0020\u007c\u0029\u0068\u0051\u005d\u003e\u005b\u002c\u003b\u006b\u003a\u0022\u0037\u0065\u0029\u0020\u005a\u006c\u0027\u0046\u0022\u006e\u003a\u0051\u0075\u0042\u0052\u0027\u0063\u003e\u006d\u0066\u0036\u003e\u0046\u004c\u0044\u002a\u0054\u003a\u0067\u0062\u007a\u0040\u002e\u0026\u0032\u0027\u0047\u006f\u0065\u0042\u0024\u0039\u0075\u0024\u0036\u007b\u003a\u0028\u0062\u0072\u0039\u0024\u0041\u005a\u0032\u003f\u002f\u0025\u0023\u006e\u005a\u004e\u003f\u0025\u007b\u003f\u004b\u006a\u0055\u0022\u0070\u0071\u006f\u0048\u0035\u0068\u0039\u002a\u005b\u007d\u0058\u0064\u0033\u0040\u0033\u0030\u0046\u002f\u0024\u006f\u003d\u003d\u0020\u006c\u003e\u0022\u007b\u0027\u006d\u0057\u0051\u0065\u0073\u0054\u004c\u006d\u005f\u0023\u005e\u003d\u007e\u0037\u0020\u002a\u0051\u0066\u0022\u0022\u0054\u0073\u0022\u006d\u0024\u0025\u007c\u004f\u0069\u0071\u0046\u003d\u0071\u003b\u0054\u0078\u005c\u003d\u0059\u0043\u006b\u006f\u004b\u0030\u0020\u0036\u0030\u0075\u0061\u002f\u0042\u0072\u002b\u0076\u005a\u0076\u002c\u0077\u004a\u0026\u0060\u0032\u0058\u0061\u006d\u0046\u005e\u0026